.energy-sim-container { padding: 20px; background: linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 50%, #e0f2f1 100%); min-height: 100vh; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; } .energy-sim-header { background: linear-gradient(135deg, #1b5e20 0%, #2e7d32 50%, #00695c 100%); color: white; padding: 30px; border-radius: 20px; margin-bottom: 24px; box-shadow: 0 8px 24px rgba(0,0,0,0.2); text-align: center; } .energy-sim-header h1 { font-size: 1.7rem; margin-bottom: 6px; } .energy-sim-header p { opacity: 0.85; margin: 0; font-size: 1rem; } .energy-sim-period-counter { text-align: center; font-size: 1.2rem; margin-bottom: 20px; color: #2e7d32; font-weight: 600; } .energy-sim-event-box { background: #fff3e0; border-left: 5px solid #ef6c00; border-radius: 10px; padding: 16px 20px; margin-bottom: 20px; box-shadow: 0 2px 8px rgba(0,0,0,0.08); } .energy-sim-event-title { font-weight: 700; color: #ef6c00; margin-bottom: 6px; font-size: 0.95rem; text-transform: uppercase; } .energy-sim-trilemma-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-bottom: 16px; } .energy-sim-trilemma-card { background: white; border-radius: 14px; padding: 18px 14px; box-shadow: 0 3px 10px rgba(0,0,0,0.08); text-align: center; transition: transform 0.3s ease; } .energy-sim-trilemma-card:hover { transform: translateY(-4px); } .energy-sim-card-icon { font-size: 1.6rem; margin-bottom: 4px; } .energy-sim-trilemma-card .energy-sim-label { color: #666; font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 6px; } .energy-sim-trilemma-card .energy-sim-value { font-size: 1.8rem; font-weight: 700; } .energy-sim-card-security .energy-sim-value { color: #1565c0; } .energy-sim-card-decarb .energy-sim-value { color: #2e7d32; } .energy-sim-card-afford .energy-sim-value { color: #ef6c00; } .energy-sim-card-financial .energy-sim-value { color: #6a1b9a; } .energy-sim-card-just .energy-sim-value { color: #00838f; } .energy-sim-card-reg .energy-sim-value { color: #4e342e; } .energy-sim-progress-bar { background: #e0e0e0; border-radius: 6px; height: 8px; margin-top: 8px; overflow: hidden; } .energy-sim-progress-fill { height: 100%; border-radius: 6px; transition: width 0.6s ease; } .energy-sim-fill-security { background: #1565c0; } .energy-sim-fill-decarb { background: #2e7d32; } .energy-sim-fill-afford { background: #ef6c00; } .energy-sim-fill-financial { background: #6a1b9a; } .energy-sim-fill-just { background: #00838f; } .energy-sim-fill-reg { background: #4e342e; } .energy-sim-trilemma-aggregate { text-align: center; font-size: 1.3rem; padding: 14px; background: white; border-radius: 12px; margin-bottom: 20px; box-shadow: 0 3px 10px rgba(0,0,0,0.08); } .energy-sim-trilemma-aggregate strong { font-size: 2rem; color: #1b5e20; } .energy-sim-info-row { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; margin-bottom: 16px; } .energy-sim-info-box { background: white; border-radius: 12px; padding: 14px; text-align: center; box-shadow: 0 2px 8px rgba(0,0,0,0.06); } .energy-sim-info-box .energy-sim-label { color: #888; font-size: 0.72rem; text-transform: uppercase; margin-bottom: 4px; } .energy-sim-info-box .energy-sim-value { font-size: 1.2rem; font-weight: 700; color: #333; } .energy-sim-capacity-row { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin-bottom: 22px; padding: 14px; background: white; border-radius: 12px; box-shadow: 0 2px 8px rgba(0,0,0,0.06); } .energy-sim-cap-item { font-size: 0.88rem; color: #555; padding: 4px 10px; } .energy-sim-cap-item strong { color: #333; } .energy-sim-cap-total { border-left: 2px solid #2e7d32; padding-left: 14px; font-weight: 600; } .energy-sim-controls { background: white; border-radius: 16px; padding: 24px; margin-bottom: 24px; box-shadow: 0 4px 14px rgba(0,0,0,0.1); } .energy-sim-controls h3 { color: #1b5e20; margin-bottom: 18px; } .energy-sim-decision-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 18px; margin-bottom: 18px; } .energy-sim-decision label { display: block; font-weight: 600; color: #444; margin-bottom: 6px; font-size: 0.88rem; } .energy-sim-decision input[type=range] { width: calc(100% - 50px); vertical-align: middle; } .energy-sim-range-val { display: inline-block; width: 44px; text-align: right; font-weight: 700; color: #1b5e20; } .energy-sim-decision select { width: 100%; padding: 6px; border-radius: 8px; border: 1px solid #ccc; } .energy-sim-budget-display { text-align: center; font-size: 1rem; padding: 10px; margin-bottom: 14px; background: #f5f5f5; border-radius: 8px; color: #555; } .energy-sim-submit { display: block; width: 100%; margin-bottom: 10px; font-size: 1.1rem; padding: 12px; background: #2e7d32; border-color: #2e7d32; border-radius: 12px; } .energy-sim-submit:hover { background: #1b5e20; border-color: #1b5e20; } .energy-sim-chart { background: white; border-radius: 14px; padding: 20px; margin-bottom: 24px; box-shadow: 0 3px 10px rgba(0,0,0,0.08); } .energy-sim-chart h4 { color: #1b5e20; margin-bottom: 12px; } .energy-sim-history { background: white; border-radius: 14px; padding: 20px; box-shadow: 0 3px 10px rgba(0,0,0,0.08); } .energy-sim-history h4 { color: #1b5e20; margin-bottom: 12px; } @media (max-width: 768px) { .energy-sim-trilemma-cards { grid-template-columns: repeat(2, 1fr); } .energy-sim-info-row { grid-template-columns: repeat(2, 1fr); } .energy-sim-decision-grid { grid-template-columns: 1fr; } }

/* ===== v1.1.0 completion debrief (append-only) ===== */
.nrg-cm { font-family: inherit; color: #1b4332; padding: 8px 4px; }
.nrg-cm-scoreblock { text-align: center; margin-bottom: 18px; }
.nrg-cm-scorenum { font-size: 3rem; font-weight: 800; line-height: 1; color: #2e7d32; }
.nrg-cm-scoremax { font-size: 1.2rem; font-weight: 600; color: #a0aec0; }
.nrg-cm-scorelabel { font-size: .82rem; text-transform: uppercase; letter-spacing: .05em; color: #718096; margin-top: 4px; }
.nrg-cm-grade { font-size: 1.35rem; font-weight: 700; margin-top: 8px; color: #1b5e20; }
.nrg-cm-badge { display: inline-block; margin-top: 10px; padding: 5px 14px; border-radius: 999px; font-size: .85rem; font-weight: 700; }
.nrg-cm-badge-pass { background: #c6f6d5; color: #22543d; }
.nrg-cm-badge-miss { background: #fed7d7; color: #742a2a; }
.nrg-cm-kpis { display: flex; flex-wrap: wrap; gap: 12px; justify-content: center; margin: 18px 0; }
.nrg-cm-kpi { flex: 1 1 130px; max-width: 200px; background: #f1f8f4; border: 1px solid #d7ebde; border-radius: 10px; padding: 12px; text-align: center; }
.nrg-cm-kpi-val { font-size: 1.4rem; font-weight: 800; color: #1b5e20; }
.nrg-cm-kpi-label { font-size: .76rem; color: #718096; margin-top: 4px; }
.nrg-cm-insights { margin-top: 16px; background: #edf7ee; border-left: 4px solid #2e7d32; border-radius: 6px; padding: 12px 16px; }
.nrg-cm-insights h6 { margin: 0 0 8px; font-weight: 700; color: #1b5e20; }
.nrg-cm-insights ul { margin: 0; padding-left: 18px; }
.nrg-cm-insights li { margin-bottom: 6px; line-height: 1.4; }
.nrg-cm-footer { margin-top: 16px; text-align: center; font-size: .85rem; color: #a0aec0; }
